   — Add $data property array and implement form(Form $form): Form using Filament\Forms\Form with schema: [DatePicker from label 'من', DatePicker to label 'إلى', Select organization_id label 'الجهة' with options from Organization::withoutGlobalScopes()->pluck('name','id'), Select leave_type_id label 'نوع الإجازة' from LeaveType::active()->pluck('name','id'), Select status label 'الحالة' with options from LeaveStatus cases using label() as display].
