   — Add exportExcel() action method: $data=$this->form->getState(); return Excel::download(new LeaveRequestsExport($data),'leave-report-'.now()->format('Y-m-d').'.xlsx').
   — Add exportPdf() action method: $data=$this->form->getState(); $pdf=app(ReportPdfService::class)->generateSummary($data); return response()->make($pdf,200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename=report-'.now()->format('Y-m-d').'.pdf']).
